import { beforeEach, describe, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
	callServerTool: vi.fn().mockResolvedValue({ isError: false }),
	connect: vi.fn().mockResolvedValue(undefined),
	hostContext: {} as Record<string, unknown>,
	listeners: new Map<string, Set<(params: unknown) => void>>(),
}));

vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) {
			const handlers = bridge.listeners.get(name) ?? new Set();
			handlers.add(handler);
			bridge.listeners.set(name, handlers);
		}
		removeEventListener(name: string, handler: (params: unknown) => void) {
			bridge.listeners.get(name)?.delete(handler);
		}
		callServerTool = bridge.callServerTool;
		connect = bridge.connect;
		getHostContext() { return { theme: "light", ...bridge.hostContext }; }
		async openLink() { return { isError: false }; }
	},
	PostMessageTransport: class { async close() {} },
}));

describe("cross-target standard output probe", () => {
	beforeEach(() => {
		vi.resetModules();
		vi.clearAllMocks();
		bridge.listeners.clear();
		bridge.hostContext = {};
	});

	it("keeps stale outer metadata off authoritative standard output", async () => {
		const parent = Object.assign(new EventTarget(), {
			location: { origin: window.location.origin },
		});
		Object.defineProperty(window, "parent", { configurable: true, value: parent });
		bridge.callServerTool.mockImplementation(async ({ name, arguments: args }) => {
			if (name === "restore_lobu_app_result" && args.snapshot_capability === "stale") {
				return { isError: false, structuredContent: {
					found: true,
					tool_name: "query_sdk",
					data: { title: "Stale outer card" },
					view_state: { "details.open": true },
				} };
			}
			return { isError: false, structuredContent: { saved: true } };
		});

		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data, viewState } = useMcpApp<{ title: string }>();
			return <><span>{data?.title ?? "none"}</span><span>open:{String(viewState["details.open"])}</span></>;
		}
		render(<Provider devMock={{ title: "dev" }}><Probe /></Provider>);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalled());

		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({ structuredContent: { title: "Current standard card" } });
			}
		});
		expect(await screen.findByText("Current standard card")).toBeInTheDocument();

		act(() => {
			parent.dispatchEvent(new CustomEvent("openai:set_globals", { detail: { globals: {
				toolResponseMetadata: { mcp_tool_result: { _meta: {
					"lobu/mcp-app-snapshot-capability": "stale",
				} } },
			} } }));
		});

		await waitFor(() => expect(bridge.callServerTool).toHaveBeenCalledWith({
			name: "restore_lobu_app_result",
			arguments: { snapshot_capability: "stale" },
		}));
		expect(screen.getByText("Current standard card")).toBeInTheDocument();
		expect(screen.getByText("open:undefined")).toBeInTheDocument();
	});
});
